import { randomUUID } from 'node:crypto';
import { mkdir, open, readFile, rename, rm } from 'node:fs/promises';
import { basename, dirname, join } from 'node:path';

/** Publish generated bytes without truncating the copy an application is reading.
 * Skip identical files; verify the written bytes before the atomic replacement. */
export async function writeAssetCopy(destination, bytes) {
  const previous = await readFile(destination).catch(error => {
    if (error.code === 'ENOENT') return undefined;
    throw error;
  });
  if (previous?.equals(bytes)) return false;
  await mkdir(dirname(destination), { recursive: true });
  const temporary = join(dirname(destination), `.${basename(destination)}.${randomUUID()}.tmp`);
  let handle;
  try {
    handle = await open(temporary, 'wx', 0o644);
    await handle.writeFile(bytes);
    await handle.sync();
    await handle.close();
    handle = undefined;
    if (!(await readFile(temporary)).equals(bytes)) throw new Error(`Generated asset write verification failed: ${destination}`);
    await rename(temporary, destination);
    if (!(await readFile(destination)).equals(bytes)) throw new Error(`Generated asset replacement verification failed: ${destination}`);
    return true;
  } finally {
    await handle?.close().catch(() => {});
    await rm(temporary, { force: true });
  }
}
